\decprob{Biclique}
{An undirected bipartite graph $G=(V=A\uplus B,E)$ and an integer~$k$.}
{Is there a vertex set $X\subseteq V$ of $G$ such that $|X\cap A|=|X\cap B|= k$ and all vertices in $X\cap A$ are adjacent with all vertices in $X\cap B$?}

\decprob{Clique}
{An undirected graph $G=(V,E)$ and an integer~$k$.}
{Is there a vertex set $X\subseteq V$ of $G$ such that $|X|\geq k$ and all vertices in $X$ are pairwise adjacent in $G$?}

\decprob{CNF Sat}
{Given a Boolean formula~$\phi$ in conjunctive normal form (CNF).}
{Is $\phi$ satisfiable?}

\decprob{Colorful Graph Motif}
{An undirected graph $G=(V,E)$, an integer $k$, and a vertex coloring function $\mathrm{col}:V \to \{1,\ldots,k\}$.}
{Is there a vertex set~$X\subseteq V$ such that $G[X]$ is connected and $X$ contains exactly one vertex of each color?}

\decprob{Connected Vertex Cover}
{An undirected graph $G=(V,E)$ and an integer~$k$.}
{Is there a vertex set $X\subseteq V$ in $G$ with $|X|\le k$ and each edge of $G$ is incident to at least one vertex in $X$ and $G[X]$ is connected?}

\decprob{Directed Path}
{A directed graph~$G=(V,E)$ and an integer~$k$.}
{Is there a simple directed path $P$ of length at least~$k$ in~$G$?}

\decprob{Hamiltonian Path}
{An undirected graph~$G=(V,E)$.}
{Is there a path in $G$ that visits each vertex exactly once?}

\decprob{Hitting Set}
{Given a universe $U$, a family $\mathcal{F}\subseteq 2^U$ of subsets of $U$, and an integer~$k$.}
{Is there a subset $U'\subseteq U$ such that $|U'|\leq k$ and $F\cap U'\neq \emptyset$ for all $F\in\mathcal{F}$?}

\decprob{Independent Set}
{An undirected graph $G=(V,E)$ and an integer~$k$.}
{Is there a vertex set $X\subseteq V$ of $G$ such that $|X|\geq k$ and $G[X]$ is edge-free?}

\decprob{Internal Steiner Tree}
{An undirected graph $G=(V=N\uplus T,E)$ and an integer~$k$.}
{Is there a subgraph~$H$ of~$G$ such that $H$ is a tree with~$T$ being part of its internal vertices?}

\decprob{$k$-CNF Sat}
{Given a Boolean formula~$\phi$ in conjunctive normal form (CNF) with at most $k$ literals in each clause.}
{Is $\phi$ satisfiable?}

\decprob{Multicolored Path}
{An undirected graph~$G=(V,E)$ and a vertex coloring function $\mathrm{col}:V \to \{1,\ldots,k\}$.}
{Is there a simple path $P$ in $G$ that contains exactly one vertex of each color?}

\decprob{Path}
{An undirected graph~$G=(V,E)$ and an integer~$k$.}
{Is there a simple path $P$ of length at least~$k$ in~$G$?}

\decprob{Rooted Path}
{An undirected graph~$G=(V,E)$, an integer~$k$, and a root vertex $r\in V$.}
{Is there a simple path $P$ of length at least~$k$ in~$G$ starting at root vertex~$r$?}

\decprob{Set Cover}
{Given a universe $U$, a family of sets $\mathcal{F}\subseteq 2^U$, and an integer~$k$.}
{Is there a subset $\mathcal{C}\subseteq \mathcal{F}$ such that $|\mathcal{C}|\leq k$ and $U=\bigcup_{C\in \mathcal{C}} C$?}

\decprob{Short Binary NTM Computation}
{Given a single-tape, single-head, non-deterministic Turing machine $M=(\Sigma, Q, q_0, F, \delta)$, where $\Sigma$ is an alphabet of size two, that is $|\Sigma| = 2$, $Q$ is the set of states, $q_0\in Q$ is the initial state, $F\subseteq Q$ are the accepting states, and $\delta \subseteq ((\Sigma\cup\{\square\}) \times Q)\times (\Sigma\times Q\times \{-1, 0, 1\})$ is the transition relation, where $\square$ denotes the blank symbol in an empty cell, a word $x\in\Sigma^*$, and an integer $k$ unary encoding.}
{Does $M$ reach an accepting state after $k$ computation steps if the word initially written on the tape is $x$?}

\decprob{Short NTM Computation}
{Given a single-tape, single-head, non-deterministic Turing machine $M=(\Sigma, Q, q_0, F, \delta)$, where $\Sigma$ is the alphabet, $Q$ is the set of states, $q_0\in Q$ is the initial state, $F\subseteq Q$ are the accepting states, and $\delta \subseteq ((\Sigma\cup\{\square\}) \times Q)\times (\Sigma\times Q\times \{-1, 0, 1\})$ is the transition relation, where $\square$ denotes the blank symbol in an empty cell, a word $x\in\Sigma^*$, and an integer $k$ unary encoding.}
{Does $M$ reach an accepting state after $k$ computation steps if the word initially written on the tape is $x$?}

\decprob{Terminal Steiner Tree}
{An undirected graph $G=(V=N\uplus T,E)$ and an integer~$k$.}
{Is there a subgraph~$H$ of~$G$ such that $H$ is a tree with~$T$ being its set of leaves?}

\decprob{Vertex Cover}
{An undirected graph $G=(V,E)$ and an integer~$k$.}
{Is there a vertex set $X\subseteq V$ in $G$ with $|X|\le k$ and each edge of $G$ is incident to at least one vertex in $X$?}
